function wChart(ws, band){ if(!ws.length) return '<div class="ptEmpty">' + L("Timbang setiap bulan untuk lihat trend.", "Weigh monthly to see the trend.") + '</div>';
  var W = 300, Hh = 120, ks = ws.map(function(w){ return +w.kg; }), lo = Math.min.apply(null, ks.concat(band ? [band[0]] : [])) * 0.9, hi = Math.max.apply(null, ks.concat(band ? [band[1]] : [])) * 1.1 || 1, y = function(v){ return Hh - 10 - (v - lo) / (hi - lo || 1) * (Hh - 20); }, x = function(i){ return 16 + (ws.length < 2 ? (W - 32) / 2 : i * (W - 32) / (ws.length - 1)); };
  var path = ws.map(function(w, i){ return (i ? "L" : "M") + x(i).toFixed(1) + " " + y(+w.kg).toFixed(1); }).join(" ");
  return '<svg class="ptChart" viewBox="0 0 ' + W + ' ' + Hh + '">' + (band ? '<rect x="0" y="' + y(band[1]).toFixed(1) + '" width="' + W + '" height="' + (y(band[0]) - y(band[1])).toFixed(1) + '" class="band"/>' : '') + '<path d="' + path + '" class="ln"/>' + ws.map(function(w, i){ return '<circle cx="' + x(i).toFixed(1) + '" cy="' + y(+w.kg).toFixed(1) + '" r="4"/>'; }).join("") + '<text x="' + (W - 4) + '" y="14" text-anchor="end">' + ks[ks.length - 1] + ' kg</text></svg>'; }
