function tracker(p, e){ try{ var x = H.load("ihsan_expense", null) || {}; x.tx = x.tx || []; var id = "pt" + e.id; x.tx.push({id: id, t: "out", amt: Math.round(e.amt * 100), cat: "pets", note: "🐾 " + p.n + ": " + (e.note || T(EXC.filter(function(c){ return c[0] === e.cat; })[0] ? L(EXC.filter(function(c){ return c[0] === e.cat; })[0][2], EXC.filter(function(c){ return c[0] === e.cat; })[0][3]) : "")), pay: "card", date: e.d, src: "pets"}); H.save("ihsan_expense", x); return id; }catch(err){ return ""; } }
