  var go = function(){ var pr = "You read a photo for a pet owner in Malaysia: a vaccination card, a vet clinic receipt or a pet shop receipt. Today is " + ymd() + ". Reply ONLY with JSON: {\"kind\":\"vaccine|visit|receipt\",\"clinic\":\"\",\"vaccines\":[{\"name\":\"\",\"date\":\"YYYY-MM-DD\",\"next\":\"YYYY-MM-DD or empty\"}],\"visit\":{\"date\":\"YYYY-MM-DD\",\"reason\":\"\",\"notes\":\"\",\"total\":0},\"items\":[{\"name\":\"\",\"amount\":0,\"category\":\"food|vet|toys|groom|supply|other\"}]}. Amounts in RM. Leave lists empty when not shown.";
    window.HalalAI.complete([{role: "user", content: [{type: "text", text: pr}, {type: "image_url", image_url: {url: img}}]}], 2000, function(a, b){ return L(a, b); }, "", "pets").then(function(r){ var t = String(r && r.text || "").replace(/```json|```/g, ""), j = null; try{ j = JSON.parse(t.slice(t.indexOf("{"), t.lastIndexOf("}") + 1)); }catch(e){} if(!j) throw new Error(L("Jawapan AI tidak dapat dibaca.", "The AI's reply could not be read.")); H.closeOverlay(); review(p, j); }).catch(function(e){ H.closeOverlay(); toast("⚠️ " + (e && e.message || e)); }); };
